#include "CadDocument.h"
#include "SketchGeometry.h"
#include "SketchAxis3d.h"
#include "SketchRotate.h"
#include <QCoreApplication>
#include <QTemporaryDir>
#include <cmath>
#include <iostream>
#include <numbers>
#include <stdexcept>
void check(bool v,const QString& s){if(!v)throw std::runtime_error(s.toStdString());}
int main(int argc,char** argv){QCoreApplication app(argc,argv);try{CadDocument doc;auto source=SketchGeometry::newFeature(doc.authored()["documentId"].toString(),"XY");const double xy[4][2]={{12,6},{32,10},{27,22},{9,18}};for(int n=0;n<4;++n)source=SketchGeometry::addLine(source,{{"u1Mm",xy[n][0]},{"v1Mm",xy[n][1]},{"u2Mm",xy[(n+1)%4][0]},{"v2Mm",xy[(n+1)%4][1]}});auto p=source["parameters"].toObject();auto points=p["points"].toArray();for(int n=0;n<5;++n){const int a=n<4?n:0,b=n<4?(n+1)%4:2;const auto r=SketchGeometry::addDimension(source,{{"kind","linear"},{"pointIds",QJsonArray{points[a].toObject()["id"],points[b].toObject()["id"]}},{"valueMm",std::hypot(xy[a][0]-xy[b][0],xy[a][1]-xy[b][1])},{"driving",true}});check(r.ok,r.error);source=r.feature;}p=SketchAxis3d::upsert(source["parameters"].toObject(),4,3,10);source["parameters"]=p;const auto axis=p["constructionLines3d"].toArray().first().toObject();QJsonArray ids;for(const auto& v:p["entities"].toArray())ids.append(v.toObject()["id"]);const auto before=SketchGeometry::evaluateFeature(source);
 auto rotated=SketchGeometry::retainedRotate(source,{{"entityIds",ids},{"axisLineId",axis["id"]},{"angleDeg",30}});check(rotated.ok,rotated.error);const auto group=rotated.feature["parameters"].toObject()["rotateGroups"].toArray().first().toObject();auto verify=[&](const QJsonObject& f,double deg,double x=4,double y=3){const auto pp=f["parameters"].toObject()["points"].toArray();for(int n=0;n<4;++n){const double t=deg*std::numbers::pi/180,u=xy[n][0]-x,v=xy[n][1]-y;check(std::abs(pp[n].toObject()["uMm"].toDouble()-(x+u*std::cos(t)-v*std::sin(t)))<1e-6 && std::abs(pp[n].toObject()["vMm"].toDouble()-(y+u*std::sin(t)+v*std::cos(t)))<1e-6,"Analytic rotate vertex");}const auto e=SketchGeometry::evaluateFeature(f);check(e.profiles.size()==1 && e.profiles[0].profileId==before.profiles[0].profileId,"Profile identity");};verify(rotated.feature,30);
 for(int n=0;n<2;++n){const auto r=SketchGeometry::solveDraft(rotated.feature);check(r.ok && r.feature==rotated.feature,"Idempotent source-only solve: "+r.error);}const auto edited=SketchGeometry::retainedRotate(rotated.feature,{{"groupId",group["id"]},{"axisLineId",axis["id"]},{"angleDeg",-15}});check(edited.ok,edited.error);verify(edited.feature,-15);check(edited.feature["parameters"].toObject()["rotateGroups"].toArray().first().toObject()["sourcePoints"]==group["sourcePoints"],"Edit replaces angle over same source");auto pivot=edited.feature;pivot["parameters"]=SketchAxis3d::upsert(pivot["parameters"].toObject(),6,5,12,axis["id"].toString());const auto pivotSolve=SketchGeometry::solveDraft(pivot);check(pivotSolve.ok,pivotSolve.error);verify(pivotSolve.feature,-15,6,5);
 const auto distant=SketchGeometry::addStandalonePoint(source,{{"uMm",100},{"vMm",100}});check(distant.ok,distant.error);const auto isolated=SketchGeometry::retainedRotate(distant.feature,{{"entityIds",ids},{"axisLineId",axis["id"]},{"angleDeg",30}});check(isolated.ok,isolated.error);check(isolated.feature["parameters"].toObject()["points"].toArray().last()==distant.feature["parameters"].toObject()["points"].toArray().last(),"Unselected point remains exact");
 auto anchor=SketchGeometry::addStandalonePoint(source,{{"uMm",12},{"vMm",6}});check(anchor.ok,anchor.error);const auto anchorId=anchor.feature["parameters"].toObject()["entities"].toArray().last().toObject()["pointId"];const auto linked=SketchGeometry::addConstraint(anchor.feature,{{"type","coincident"},{"pointIds",QJsonArray{points[0].toObject()["id"],anchorId}}});check(linked.ok,linked.error);const auto denied=SketchGeometry::retainedRotate(linked.feature,{{"entityIds",ids},{"axisLineId",axis["id"]},{"angleDeg",30}});check(!denied.ok && denied.feature==linked.feature,"External anchor refuses atomically");
 check(!SketchGeometry::movePoint(edited.feature,{{"pointId",points[0].toObject()["id"]},{"uMm",1},{"vMm",1}}).ok,"Output drag refuses");check(!SketchGeometry::deleteEntities(edited.feature,ids,{}).ok,"Output Delete refuses");const auto dimension=p["dimensions"].toArray().first().toObject();check(!SketchGeometry::updateDimension(edited.feature,{{"dimensionId",dimension["id"]},{"valueMm",25}}).ok,"Source size edit deferred");bool refused=false;try{SketchAxis3d::erase(edited.feature["parameters"].toObject(),axis["id"].toString());}catch(const std::exception&){refused=true;}check(refused,"Referenced axis Delete refuses");
 for(const auto& args:QJsonArray{QJsonObject{{"entityIds",QJsonArray{ids[0],ids[1],ids[2]}},{"axisLineId",axis["id"]},{"angleDeg",30}},QJsonObject{{"entityIds",ids},{"axisLineId",ids[0]},{"angleDeg",30}},QJsonObject{{"groupId",""},{"angleDeg",30}},QJsonObject{{"entityIds",ids},{"axisLineId",axis["id"]},{"angleDeg",0}}}){const auto r=SketchGeometry::retainedRotate(source,args.toObject());check(!r.ok && r.feature==source,"Atomic bad selection/axis/zero/empty group refusal");}
 auto conflict=SketchGeometry::newFeature(doc.authored()["documentId"].toString(),"XY");conflict=SketchGeometry::addRectangle(conflict,{{"u1Mm",0},{"v1Mm",0},{"u2Mm",20},{"v2Mm",12}});auto cp=conflict["parameters"].toObject();cp=SketchAxis3d::upsert(cp,4,3,10);conflict["parameters"]=cp;QJsonArray cids;for(const auto& v:cp["entities"].toArray())cids.append(v.toObject()["id"]);const auto r=SketchGeometry::retainedRotate(conflict,{{"entityIds",cids},{"axisLineId",cp["constructionLines3d"].toArray().first().toObject()["id"]},{"angleDeg",30}});check(!r.ok && r.feature==conflict,"H/V conflict refuses unchanged");check(doc.commit(SketchGeometry::replaceFeature(doc.authored(),edited.feature),"Rotate").isEmpty(),"Commit");const auto authored=doc.authored();doc.history().undo();doc.history().redo();check(doc.authored()==authored,"Exact history");QTemporaryDir dir;check(doc.save(dir.filePath("rotate.alloy")).isEmpty(),"Save");CadDocument reopened;check(reopened.open(dir.filePath("rotate.alloy")).isEmpty() && reopened.authored()==authored,"Exact reopen");std::cout<<"SKETCH_ROTATE_CORE_OK\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
